import{_ as p,a0 as r,w as l,s as i,I as a,x as t,a1 as e,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"学习用 Thonny 写代码： 一个面向初学者的Python IDE | LCTT x X-CMD","titleTemplate":false,"description":"学习用 Thonny 写代码： 一个面向初学者的Python IDE | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"学习用 Thonny 写代码： 一个面向初学者的Python IDE | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"学习用 Thonny 写代码： 一个面向初学者的Python IDE | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180219 Learn to code with Thonny - a Python IDE for beginners","title":"学习用 Thonny 写代码： 一个面向初学者的Python IDE","tag":"201806","desc":""},"relativePath":"201806/20180219 Learn to code with Thonny - a Python IDE for beginners.md","filePath":"[post].md"}'),h={name:"201806/20180219 Learn to code with Thonny - a Python IDE for beginners.md"};function y(u,n,g,b,f,c){const s=r("Link");return l(),i("div",null,[n[19]||(n[19]=a("h1",{id:"学习用-thonny-写代码-一个面向初学者的python-ide",tabindex:"-1"},[t("学习用 Thonny 写代码： 一个面向初学者的Python IDE "),a("a",{class:"header-anchor",href:"#学习用-thonny-写代码-一个面向初学者的python-ide","aria-label":"Permalink to “学习用 Thonny 写代码： 一个面向初学者的Python IDE”"},"​")],-1)),n[20]||(n[20]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/02/thonny.png-945x400.jpg",alt:""})],-1)),n[21]||(n[21]=a("p",null,"学习编程很难。即使当你最终怎么正确使用你的冒号和括号，但仍然有很大的可能你的程序不会如果所想的工作。 通常，这意味着你忽略了某些东西或者误解了语言结构，你需要在代码中找到你的期望与现实存在分歧的地方。",-1)),n[22]||(n[22]=a("p",null,[t("程序员通常使用被叫做"),a("ruby",null,[t("调试器"),a("rt",null,"debugger")]),t("的工具来处理这种情况，它允许一步一步地运行他们的程序。不幸的是，大多数调试器都针对专业用途进行了优化，并假设用户已经很好地了解了语言结构的语义（例如：函数调用）。")],-1)),a("p",null,[n[1]||(n[1]=t("Thonny 是一个适合初学者的 Python IDE，由爱沙尼亚的 ",-1)),e(s,{href:"https://www.ut.ee/en"},{default:o(()=>[...n[0]||(n[0]=[t("Tartu 大学",-1)])]),_:1}),n[2]||(n[2]=t(" 开发，它采用了不同的方法，因为它的调试器是专为学习和教学编程而设计的。",-1))]),n[23]||(n[23]=d(`<p>虽然 Thonny 适用于像小白一样的初学者，但这篇文章面向那些至少具有 Python 或其他命令式语言经验的读者。</p><h3 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to “开始”">​</a></h3><p>从第 Fedora 27 开始，Thonny 就被包含在 Fedora 软件库中。 使用 <code>sudo dnf install thonny</code> 或者你选择的图形工具（比如“<ruby>软件<rt>Software</rt></ruby>”）安装它。</p><p>当第一次启动 Thonny 时，它会做一些准备工作，然后呈现一个空白的编辑器和 Python shell 。将下列程序文本复制到编辑器中，并将其保存到文件中（<code>Ctrl+S</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>n = 1</span></span>
<span class="line"><span>while n &lt; 5:</span></span>
<span class="line"><span>    print(n * &quot;*&quot;)</span></span>
<span class="line"><span>    n = n + 1</span></span></code></pre></div><p>我们首先运行该程序。 为此请按键盘上的 <code>F5</code> 键。 你应该看到一个由星号组成的三角形出现在 shell 窗格中。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/scr1.png" alt="一个简单的 Thonny 程序"></p><p>Python 分析了你的代码并理解了你想打印一个三角形了吗？让我们看看！</p><p>首先从“<ruby>查看<rt>View</rt></ruby>”菜单中选择“<ruby>变量<rt>Variables</rt></ruby>”。这将打开一张表格，向我们展示 Python 是如何管理程序的变量的。现在通过按 <code>Ctrl + F5</code>（在 XFCE 中是 <code>Ctrl + Shift + F5</code>）以调试模式运行程序。在这种模式下，Thonny 使 Python 在每一步所需的步骤之前暂停。你应该看到程序的第一行被一个框包围。我们将这称为焦点，它表明 Python 将接下来要执行的部分代码。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr2.png" alt=" Thonny 调试器焦点 "></p><p>你在焦点框中看到的一段代码段被称为赋值语句。 对于这种声明，Python 应该计算右边的表达式，并将值存储在左边显示的名称下。按 <code>F7</code> 进行下一步。你将看到 Python 将重点放在语句的正确部分。在这个例子中，表达式实际上很简单，但是为了通用性，Thonny 提供了表达式计算框，它允许将表达式转换为值。再次按 <code>F7</code> 将文字 <code>1</code> 转换为值 <code>1</code>。现在 Python 已经准备好执行实际的赋值—再次按 <code>F7</code>，你应该会看到变量 <code>n</code> 的值为 <code>1</code> 的变量出现在变量表中。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr3.png" alt="Thonny 变量表"></p><p>继续按 <code>F7</code> 并观察 Python 如何以非常小的步骤前进。它看起来像是理解你的代码的目的或者更像是一个愚蠢的遵循简单规则的机器？</p><h3 id="函数调用" tabindex="-1">函数调用 <a class="header-anchor" href="#函数调用" aria-label="Permalink to “函数调用”">​</a></h3><p><ruby>函数调用<rt>Function Call</rt></ruby>是一种编程概念，它常常给初学者带来很大的困惑。从表面上看，没有什么复杂的事情——给代码命名，然后在代码中的其他地方引用它（调用它）。传统的调试器告诉我们，当你进入调用时，焦点跳转到函数定义中（然后稍后神奇地返回到原来的位置）。这是整件事吗？这需要我们关心吗？</p><p>结果证明，“跳转模型” 只对最简单的函数是足够的。理解参数传递、局部变量、返回和递归都得理解堆栈框架的概念。幸运的是，Thonny 可以直观地解释这个概念，而无需在厚厚的掩盖下搜索重要的细节。</p><p>将以下递归程序复制到 Thonny 并以调试模式（<code>Ctrl+F5</code> 或 <code>Ctrl+Shift+F5</code>）运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def factorial(n):</span></span>
<span class="line"><span>    if n == 0:</span></span>
<span class="line"><span>        return 1</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        return factorial(n-1) * n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(factorial(4))</span></span></code></pre></div><p>重复按 <code>F7</code>，直到你在对话框中看到表达式 <code>factorial(4)</code>。 当你进行下一步时，你会看到 Thonny 打开一个包含了函数代码、另一个变量表和另一个焦点框的新窗口（移动窗口以查看旧的焦点框仍然存在）。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr4.png" alt="通过递归函数的 Thonny"></p><p>此窗口表示堆栈帧，即用于解析函数调用的工作区。几个放在彼此顶部的这样的窗口称为<ruby>调用堆栈<rt>call stack</rt></ruby>。注意调用位置的参数 <code>4</code> 与 “局部变量” 表中的输入 <code>n</code> 之间的关系。继续按 <code>F7</code> 步进, 观察在每次调用时如何创建新窗口并在函数代码完成时被销毁，以及如何用返回值替换了调用位置。</p><h3 id="值与参考" tabindex="-1">值与参考 <a class="header-anchor" href="#值与参考" aria-label="Permalink to “值与参考”">​</a></h3><p>现在，让我们在 Python shell 中进行一个实验。首先输入下面屏幕截图中显示的语句：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr5.png" alt="Thonny shell 显示列表突变"></p><p>正如你所看到的, 我们追加到列表 <code>b</code>, 但列表 <code>a</code> 也得到了更新。你可能知道为什么会发生这种情况, 但是对初学者来说，什么才是最好的解释呢？</p><p>当教我的学生列表时，我告诉他们我一直欺骗了他们关于 Python 内存模型。实际上，它并不像变量表所显示的那样简单。我告诉他们重新启动解释器（工具栏上的红色按钮），从“<ruby>查看<rt>View</rt></ruby>”菜单中选择“<ruby>堆<rt>Heap</rt></ruby>”，然后再次进行相同的实验。如果这样做，你就会发现变量表不再包含值——它们实际上位于另一个名为“<ruby>堆<rt>Heap</rt></ruby>”的表中。变量表的作用实际上是将变量名映射到地址（或称 ID），地址又指向了<ruby>堆<rt>Heap</rt></ruby>表中的行。由于赋值仅更改变量表，因此语句 <code>b = a</code> 只复制对列表的引用，而不是列表本身。这解释了为什么我们通过这两个变量看到了变化。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr6.png" alt="在堆模式中的 Thonny"></p><p>（为什么我要在教列表的主题之前推迟说出内存模型的事实？Python 存储的列表是否有所不同？请继续使用 Thonny 的堆模式来找出结果！在评论中告诉我你认为怎么样！）</p><p>如果要更深入地了解参考系统, 请将以下程序通过打开堆表复制到 Thonny 并进行小步调试（<code>F7</code>） 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def do_something(lst, x):</span></span>
<span class="line"><span>    lst.append(x)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a = [1,2,3]</span></span>
<span class="line"><span>n = 4</span></span>
<span class="line"><span>do_something(a, n)</span></span>
<span class="line"><span>print(a)</span></span></code></pre></div><p>即使“堆模式”向我们显示真实的图片，但它使用起来也相当不方便。 因此，我建议你现在切换回普通模式（取消选择“<ruby>查看<rt>View</rt></ruby>”菜单中的“<ruby>堆<rt>Heap</rt></ruby>”），但请记住，真实模型包含变量、参考和值。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>我在这篇文章中提及到的特性是创建 Thonny 的主要原因。很容易对函数调用和引用形成错误的理解，但传统的调试器并不能真正帮助减少混淆。</p>`,33)),a("p",null,[n[4]||(n[4]=t("除了这些显著的特性，Thonny 还提供了其他几个初学者友好的工具。 请查看 ",-1)),e(s,{href:"http://thonny.org"},{default:o(()=>[...n[3]||(n[3]=[t("Thonny的主页",-1)])]),_:1}),n[5]||(n[5]=t(" 以了解更多信息！",-1))]),n[24]||(n[24]=a("hr",null,null,-1)),a("p",null,[n[7]||(n[7]=t("via: ",-1)),e(s,{href:"https://fedoramagazine.org/learn-code-thonny-python-ide-beginners/"},{default:o(()=>[...n[6]||(n[6]=[t("https://fedoramagazine.org/learn-code-thonny-python-ide-beginners/",-1)])]),_:1})]),a("p",null,[n[11]||(n[11]=t("作者：",-1)),e(s,{href:"https://fedoramagazine.org/"},{default:o(()=>[...n[8]||(n[8]=[t("Aivar Annamaa",-1)])]),_:1}),n[12]||(n[12]=t(" 译者：",-1)),e(s,{href:"https://github.com/Auk7F7"},{default:o(()=>[...n[9]||(n[9]=[t("Auk7F7",-1)])]),_:1}),n[13]||(n[13]=t(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...n[10]||(n[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[n[16]||(n[16]=t("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[14]||(n[14]=[t("LCTT",-1)])]),_:1}),n[17]||(n[17]=t(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...n[15]||(n[15]=[t("Linux中国",-1)])]),_:1}),n[18]||(n[18]=t(" 荣誉推出",-1))])])}const P=p(h,[["render",y]]);export{k as __pageData,P as default};
